package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
)

var (
	webhookSecret = os.Getenv("WEBHOOK_SECRET")
	workspaceRoot = "/var/ci/workspaces"
	allowedRepos  = map[string]bool{
		"acme/frontend": true,
		"acme/backend":  true,
		"acme/infra":    true,
	}
	// Only allow safe branch name characters
	branchPattern = regexp.MustCompile(`^[a-zA-Z0-9._/-]+$`)
	// Commit IDs must be hex SHAs (40 for SHA-1, 64 for SHA-256)
	commitPattern = regexp.MustCompile(`^[0-9a-fA-F]{40}$|^[0-9a-fA-F]{64}$`)
)

type WebhookPayload struct {
	Ref        string `json:"ref"`
	Repository struct {
		FullName string `json:"full_name"`
		CloneURL string `json:"clone_url"`
	} `json:"repository"`
	HeadCommit struct {
		ID      string `json:"id"`
		Message string `json:"message"`
	} `json:"head_commit"`
}

func verifySignature(payload []byte, signature string) bool {
	if webhookSecret == "" {
		return false
	}
	mac := hmac.New(sha256.New, []byte(webhookSecret))
	mac.Write(payload)
	expected := "sha256=" + hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(signature))
}

func sanitizeBranchName(ref string) (string, error) {
	branch := strings.TrimPrefix(ref, "refs/heads/")
	if !branchPattern.MatchString(branch) {
		return "", fmt.Errorf("invalid branch name: %s", branch)
	}
	return branch, nil
}

func sanitizeCommitID(commitID string) (string, error) {
	if !commitPattern.MatchString(commitID) {
		return "", fmt.Errorf("invalid commit id")
	}
	return commitID, nil
}

func resolveWorkspace(repo, branch string) (string, error) {
	safeRoot, err := filepath.Abs(workspaceRoot)
	if err != nil {
		return "", err
	}
	safeRepo := strings.ReplaceAll(repo, "/", "_")
	ws := filepath.Join(safeRoot, safeRepo, branch)
	abs, err := filepath.Abs(ws)
	if err != nil {
		return "", err
	}
	// Ensure the resolved path is strictly within the workspace root,
	// using a trailing separator to avoid sibling-prefix bypasses.
	if abs != safeRoot && !strings.HasPrefix(abs, safeRoot+string(os.PathSeparator)) {
		return "", fmt.Errorf("path traversal detected")
	}
	return abs, nil
}

// buildEnvFromHeaders extracts CI metadata from reverse proxy headers
// The reverse proxy (nginx) sets these from authenticated upstream context
func buildEnvFromHeaders(r *http.Request) []string {
	env := os.Environ()
	// Trusted headers set by our nginx reverse proxy after auth
	if v := r.Header.Get("X-CI-Runner-ID"); v != "" {
		env = append(env, "CI_RUNNER_ID="+v)
	}
	if v := r.Header.Get("X-CI-Trigger-User"); v != "" {
		env = append(env, "CI_TRIGGER_USER="+v)
	}
	// Build options forwarded from the proxy's auth layer
	if v := r.Header.Get("X-CI-Build-Options"); v != "" {
		env = append(env, "CI_BUILD_OPTIONS="+v)
	}
	return env
}

func executePipeline(workspace, cloneURL, branch, commitID string, env []string) error {
	if err := os.MkdirAll(workspace, 0750); err != nil {
		return fmt.Errorf("failed to create workspace: %w", err)
	}

	// Clone or fetch
	gitDir := filepath.Join(workspace, ".git")
	if _, err := os.Stat(gitDir); os.IsNotExist(err) {
		cmd := exec.Command("git", "clone", "--branch", branch, "--single-branch", cloneURL, workspace)
		cmd.Env = env
		if out, err := cmd.CombinedOutput(); err != nil {
			return fmt.Errorf("clone failed: %s: %w", string(out), err)
		}
	} else {
		cmd := exec.Command("git", "-C", workspace, "fetch", "origin", branch)
		cmd.Env = env
		if out, err := cmd.CombinedOutput(); err != nil {
			return fmt.Errorf("fetch failed: %s: %w", string(out), err)
		}
	}

	// Checkout specific commit (commitID already validated as a hex SHA;
	// use '--' to ensure it is treated as a revision, not an option).
	checkout := exec.Command("git", "-C", workspace, "checkout", "--detach", commitID, "--")
	checkout.Env = env
	if out, err := checkout.CombinedOutput(); err != nil {
		return fmt.Errorf("checkout failed: %s: %w", string(out), err)
	}

	// Execute the CI script defined in the repo
	ciScript := filepath.Join(workspace, ".ci", "build.sh")
	if _, err := os.Stat(ciScript); err != nil {
		return fmt.Errorf("no CI script found: %w", err)
	}

	// Run build with options passed as separate arguments
	buildCmd := constructBuildCommand(ciScript, env)
	buildCmd.Dir = workspace
	buildCmd.Env = env
	if out, err := buildCmd.CombinedOutput(); err != nil {
		return fmt.Errorf("build failed: %s: %w", string(out), err)
	}

	return nil
}

func constructBuildCommand(scriptPath string, env []string) *exec.Cmd {
	// Check if there are build options to pass
	var buildOpts string
	for _, e := range env {
		if strings.HasPrefix(e, "CI_BUILD_OPTIONS=") {
			buildOpts = strings.TrimPrefix(e, "CI_BUILD_OPTIONS=")
			break
		}
	}

	if buildOpts != "" {
		// Pass build options as a separate argument to avoid shell interpretation
		return exec.Command("sh", scriptPath, buildOpts)
	}
	return exec.Command("sh", scriptPath)
}

func webhookHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		http.Error(w, "read error", http.StatusBadRequest)
		return
	}

	signature := r.Header.Get("X-Hub-Signature-256")
	if !verifySignature(body, signature) {
		http.Error(w, "invalid signature", http.StatusUnauthorized)
		return
	}

	var payload WebhookPayload
	if err := json.Unmarshal(body, &payload); err != nil {
		http.Error(w, "invalid payload", http.StatusBadRequest)
		return
	}

	if !allowedRepos[payload.Repository.FullName] {
		http.Error(w, "repository not allowed", http.StatusForbidden)
		return
	}

	branch, err := sanitizeBranchName(payload.Ref)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	commitID, err := sanitizeCommitID(payload.HeadCommit.ID)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	workspace, err := resolveWorkspace(payload.Repository.FullName, branch)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	env := buildEnvFromHeaders(r)

	go func() {
		if err := executePipeline(workspace, payload.Repository.CloneURL, branch, commitID, env); err != nil {
			fmt.Fprintf(os.Stderr, "pipeline error: %v\n", err)
		}
	}()

	w.WriteHeader(http.StatusAccepted)
	w.Write([]byte(`{"status":"queued"}`))
}

func main() {
	if webhookSecret == "" {
		fmt.Fprintln(os.Stderr, "WEBHOOK_SECRET must be set")
		os.Exit(1)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/webhook", webhookHandler)

	server := &http.Server{
		Addr:    ":8080",
		Handler: mux,
	}

	fmt.Println("CI webhook listener starting on :8080")
	if err := server.ListenAndServe(); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}
